import threading
import time

_seats = {}
_lock = threading.Lock()


def reserve(seat_id):
    time.sleep(0.05)  # simulate work (outside the critical section)
    with _lock:
        if seat_id in _seats:
            return False
        _seats[seat_id] = True
        return True


def is_taken(seat_id):
    return seat_id in _seats


def reserved_count():
    return len(_seats)
